/**
 * Excluded from the src/index.ts generated by ctix,
 * because this is an internal module imported only by sentry-transport.ts, error-reporter.ts and logger.ts.
 *
 * @ctix-exclude
 */
import * as Sentry from '@sentry/node'
import { detectAppRelease } from './sentry-release'

export interface SentryClientOptions {
  dsn: string
  environment?: string
}

// Shared flag so that Sentry.init() runs only once per process.
// SentryTransport can be instantiated several times (once per Logger.configure() category)
// and ErrorReporter calls this independently, so the flag lives at module scope.
let initialized = false

/**
 * Initializes the Sentry SDK once per process.
 *
 * Later calls are no-ops (the options passed first stay in effect).
 * The release is `SENTRY_RELEASE` if set, otherwise detected from the app's package.json.
 *
 * @param options Initialization options such as DSN and environment
 */
export function ensureSentryInitialized(options: SentryClientOptions): void {
  if (initialized) return
  Sentry.init({
    dsn: options.dsn,
    environment: options.environment ?? process.env.NODE_ENV ?? 'production',
    release: process.env.SENTRY_RELEASE ?? detectAppRelease(),
    // Disable Sentry's own default integrations for these events to avoid reporting them twice,
    // because the hooks at the end of logger.ts already forward them.
    integrations: (integrations) =>
      integrations.filter(
        (integration) =>
          integration.name !== 'OnUncaughtException' &&
          integration.name !== 'OnUnhandledRejection'
      ),
  })
  initialized = true
}

/**
 * Converts a Winston npm log level to a Sentry SeverityLevel.
 *
 * Winston's 'warn' is 'warning' in Sentry, so a plain cast would send an invalid level to GlitchTip.
 *
 * @param level Winston log level string
 * @returns The corresponding Sentry SeverityLevel
 */
export function toSeverityLevel(level: string): Sentry.SeverityLevel {
  return level === 'warn' ? 'warning' : (level as Sentry.SeverityLevel)
}

/**
 * Returns whether the Sentry SDK has been initialized.
 *
 * @returns true if initialized
 */
export function isSentryInitialized(): boolean {
  return initialized
}

/**
 * Resets the initialized flag.
 *
 * Called after Sentry.close() in Logger.closeAll() so that the next Logger.configure()
 * can run Sentry.init() again.
 */
export function resetSentryInitialized(): void {
  initialized = false
}
